<?php if ( ! defined( 'ABSPATH' ) ) { exit; } if ( ! is_user_logged_in() || ! sd_notifications_available() ) { return; } $result = sd_notifications_query( 'unread', 1, sd_get_option( 'sd_notification_preview_count', 5 ) ); ?><div class="sd-notification-dropdown" hidden><strong><?php esc_html_e( 'Recent notifications', 'social-discovery' ); ?></strong><?php if ( empty( $result['notifications'] ) ) : ?><p class="sd-muted"><?php esc_html_e( 'You are all caught up.', 'social-discovery' ); ?></p><?php else : foreach ( $result['notifications'] as $notification ) : ?><a href="<?php echo esc_url( sd_notification_url( $notification ) ); ?>"><?php echo esc_html( sd_notification_label( $notification ) ); ?></a><?php endforeach; endif; ?><a class="sd-text-link" href="<?php echo esc_url( sd_home_url( 'notifications' ) ); ?>"><?php esc_html_e( 'View all notifications', 'social-discovery' ); ?></a></div>
